stages=[]
for id,name,origin,era,layers,hazard,visual,rule in stage_specs:
    desc=layers.split(';')
    assert len(desc)==6
    stages.append({'id':id,'name':name,'origin':origin,'era':era,'canon_status':'released_location_adapted_to_2d','layers':[{'index':i,'name':['ciel','lointain','fond','plan_intermediaire','plan_jouable','premier_plan'][i],'parallax':[0.04,0.12,0.28,0.55,1.0,1.15][i],'content':s,'collision':i==4} for i,s in enumerate(desc)],'hazard':{'casual_enabled_by_default':False,'optional_design':hazard,'competitive_enabled':False,'minimum_warning_frames':90},'transition':{'visual':visual,'ranked_collision_changes':False,'ranked_camera_cut':False},'anchors':{'authoring_canvas_px':[3840,2160],'ground_y_px':1680,'left_bound_x':0.08,'right_bound_x':0.92,'spawn_x':[0.35,0.65],'character_feet':'ground_y','foreground_safe_height_above_ground':0.0},'fidelity_rule':rule,'source_type':'primary_game_level_reference','source_url':sm['W03']['url'] if id in ['st_cartographer_ce','st_sunaion_h5'] else (sm['W04']['url'] if id=='st_reckoning_infinite' else None),'reference_validation':'source_game_identified_exact_angle_and_layer_captures_pending','status':'planned','art_status':'not_generated','code_status':'not_implemented'})

assert len(bosses)==20 and len(stages)==24
assert len(set(b['id'] for b in bosses))==20
assert all(len(s['layers'])==6 for s in stages)
ROOT.mkdir(parents=True,exist_ok=True)
for name,data in [('bosses.json',{'schema_version':'1.0','design_hz':60,'planned_count':20,'entities':bosses}),('stages.json',{'schema_version':'1.0','planned_count':24,'planned_layer_count':144,'stages':stages}),('sources.json',{'checked_on':'2026-11-19','policy':'Sources web vérifiées et références primaires de jeux sont distinguées; aucune capture 1 à 1 n’est déclarée validée ici.','sources':sources})]:
    (ROOT/name).write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps({'bosses':len(bosses),'stages':len(stages),'layers':sum(len(x['layers']) for x in stages),'web_sources':len(sources)},ensure_ascii=False))
